import json
from pathlib import Path

import pytest

from engine_params.src.gcode.process.support_l2_metrics import (
    analyze_support_gcode,
    canonical_expected,
    metric_matches,
    validate_support_l2_behavior,
)


def test_analyze_support_gcode_extracts_semantic_metrics(tmp_path: Path):
    gcode = tmp_path / "support.gcode"
    gcode.write_text(
        """; HEADER_BLOCK_START
; generated by test
; HEADER_BLOCK_END
; EXECUTABLE_BLOCK_START
M83
T0
;LAYER_CHANGE
;Z:0.2
G1 X0 Y0 F6000
;TYPE:Support
G1 X10 Y0 E1 F3600
;TYPE:Support interface
G1 X10 Y10 E2 F4800
; EXECUTABLE_BLOCK_END
; CONFIG_BLOCK_START
support_speed = 999
; CONFIG_BLOCK_END
""",
        encoding="utf-8",
    )

    metrics = analyze_support_gcode(gcode)

    assert metrics["role.Support.move_count"] == 1
    assert metrics["role.Support.path_length"] == 10.0
    assert metrics["role.Support.speed_p50"] == 60.0
    assert metrics["role.Support interface.speed_p50"] == 80.0
    assert metrics["role.Support total.move_count"] == 2


