@pytest.mark.parametrize("marker", [";Z:", ";:", None])
def test_support_heights_use_both_comments_or_motion_z(tmp_path: Path, marker):
    gcode = tmp_path / "support_heights.gcode"
    lines = ["; EXECUTABLE_BLOCK_START", "M83"]
    for z, x in ((0.2, 10), (0.6, 20), (1.0, 30)):
        lines.append(";LAYER_CHANGE")
        if marker is not None:
            lines.append(f"{marker}{z}")
        lines.extend([f"G1 Z{z}", ";TYPE:Support", f"G1 X{x} Y0 E1"])
    lines.append("; EXECUTABLE_BLOCK_END")
    gcode.write_text("\n".join(lines), encoding="utf-8")

    metrics = analyze_support_gcode(gcode)

    assert metrics["role.Support total.z_first"] == 0.2
    assert metrics["role.Support total.z_last"] == 1.0
    assert metrics["role.Support total.z_gap_min"] == 0.4
    assert metrics["role.Support total.z_gap_p50"] == 0.4
    assert metrics["role.Support total.z_gap_max"] == 0.4
    assert metrics["role.Support total.move_count"] == 3


def test_support_layer_comment_takes_precedence_over_z_hop(tmp_path: Path):
    gcode = tmp_path / "support_hop.gcode"
    gcode.write_text(
        "; EXECUTABLE_BLOCK_START\nM83\n;LAYER_CHANGE\n;:0.2\n"
        "G1 Z0.6\n;TYPE:Support\nG1 X10 Y0 E1\n; EXECUTABLE_BLOCK_END\n",
        encoding="utf-8",
    )

    metrics = analyze_support_gcode(gcode)

    assert metrics["role.Support total.z_first"] == 0.2
    assert metrics["role.Support total.z_last"] == 0.2


def test_metric_matches_uses_exact_counts_and_tolerant_geometry():
    assert metric_matches("role.Support.move_count", 10, 10)
    assert not metric_matches("role.Support.move_count", 11, 10)
    assert metric_matches("role.Support.path_length", 100.5, 100.0)
    assert not metric_matches("role.Support.path_length", 103.0, 100.0)


def test_metric_ranges_and_numeric_expected_values_are_stable():
    assert canonical_expected(2) == canonical_expected("2")
    assert canonical_expected(0.20) == canonical_expected("0.2")
    assert metric_matches(
        "role.Support.path_length",
        112.0,
        {"min": 100.0, "max": 110.0},
        relative_tolerance=0.02,
    )
    assert not metric_matches(
        "role.Support.path_length",
        113.0,
        {"min": 100.0, "max": 110.0},
        relative_tolerance=0.02,
    )


def test_duplicate_expected_value_uses_project_name_from_gcode_path(tmp_path: Path):
    gcode = tmp_path / "test_support_type_normal_auto_painted__1.gcode"
    gcode.write_text(
        """; EXECUTABLE_BLOCK_START
M83
;LAYER_CHANGE
;Z:0.2
;TYPE:Support interface
G1 X10 Y0 E1
G1 X10 Y10 E1
; EXECUTABLE_BLOCK_END
""",
        encoding="utf-8",
    )
    baseline = tmp_path / "baseline.json"
    expected_key = canonical_expected("normal(auto)")
    baseline.write_text(
        json.dumps({
            "parameters": {
                "support_type": {
                    "checks": ["role.Support interface.bbox_area"],
                    "entries": [
                        {
                            "project_name": "normal_auto",
                            "expected_key": expected_key,
                            "metrics": {"role.Support interface.bbox_area": 100.0},
                        },
                        {
                            "project_name": "normal_auto_painted",
                            "expected_key": expected_key,
                            "metrics": {"role.Support interface.bbox_area": 25.0},
                        },
                    ],
                },
            },
        }),
        encoding="utf-8",
    )

    ok, details = validate_support_l2_behavior(
        gcode,
        "support_type",
        "normal(auto)",
        baseline,
    )

    assert not ok
    assert details["matched_project"] == "normal_auto_painted"
    assert details["mismatches"][0]["expected"] == 25.0


@pytest.mark.parametrize("project_name,expected_ok", [
    ("enabled", False),
    ("hybrid_tree_enabled", True),
    ("unknown_enabled", False),
])
def test_build_plate_only_selects_complete_case_id(tmp_path, project_name, expected_ok):
    gcode = tmp_path / f"test_support_on_build_plate_only_{project_name}__1.gcode"
    gcode.write_text(
        "; EXECUTABLE_BLOCK_START\nM83\n;LAYER_CHANGE\n;Z:0.2\n"
        ";TYPE:Support\nG1 X10 Y0 E1\n; EXECUTABLE_BLOCK_END\n",
        encoding="utf-8",
    )
    baseline = tmp_path / "baseline.json"
    metric = "role.Support total.path_length"
    baseline.write_text(json.dumps({
        "parameters": {
            "support_on_build_plate_only": {
                "checks": [metric],
                "entries": [
                    {"project_name": name, "expected_key": canonical_expected(1),
                     "metrics": {metric: length}}
                    for name, length in [("enabled", 20.0), ("hybrid_tree_enabled", 10.0)]
                ],
            },
        },
    }), encoding="utf-8")

    ok, details = validate_support_l2_behavior(
        gcode, "support_on_build_plate_only", 1, baseline,
    )

    assert ok is expected_ok
    if project_name == "unknown_enabled":
        assert "ambiguous L2 baseline candidates" in details["error"]
    else:
        assert details["matched_project"] == project_name
        if not expected_ok:
            assert details["mismatches"][0]["expected"] == 20.0
